import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
const root = path.join(path.dirname(fileURLToPath(import.meta.url)), '..');
const assets = {"public/brand/mark.png":"","public/brand/logo.png":"","public/brand/logo-full.png":"","public/icon-192.png":"","public/icon-512.png":"","public/icon-maskable-512.png":"","public/favicon-48.png":"","public/favicon.ico":"","public/apple-touch-icon.png":"","public/badge-96.png":"","public/demo/facebook-page-likes.png":"","public/demo/facebook-video-views.png":"","public/demo/instagram-followers.png":"","public/demo/instagram-likes.png":"","public/demo/instagram-views.png":"","public/demo/tiktok-followers.png":"","public/demo/tiktok-likes.png":"","public/demo/tiktok-views.png":"","public/demo/youtube-subscribers.png":"","public/demo/youtube-views.png":"","public/brand/moncash.webp":"","public/brand/natcash.webp":"","public/fonts/PlusJakartaSans-Variable.woff2":"","public/fonts/PlusJakartaSans-LatinExt-Variable.woff2":""};
for (const [rel, b64] of Object.entries(assets)) {
  const dest = path.join(root, rel);
  fs.mkdirSync(path.dirname(dest), { recursive: true });
  fs.writeFileSync(dest, Buffer.from(b64, 'base64'));
}
const missing = Object.keys(assets).filter((rel) => !fs.existsSync(path.join(root, rel)));
if (missing.length) { console.error('emit-public-assets: missing after write', missing); process.exit(1); }
console.log(`emit-public-assets: ${Object.keys(assets).length} files`);
